-- Katalog dari folder "SKU Picture" + harga/ukuran/stok file promo Shopee (Agustus). Aman dijalankan berulang.
alter table public.products add column if not exists sku text;
alter table public.products add column if not exists images jsonb not null default '[]'::jsonb;
create unique index if not exists products_sku_key on public.products (sku) where sku is not null;

-- 6 produk contoh lama disembunyikan (tidak dihapus) supaya tidak dobel dengan katalog SKU
update public.products set is_active = false where sku is null;

