on conflict (sku) where sku is not null do update set
  name = excluded.name, slug = excluded.slug, category = excluded.category, description = excluded.description, size = excluded.size,
  price = excluded.price, min_order = excluded.min_order, stock_qty = excluded.stock_qty, image_url = excluded.image_url, images = excluded.images,
  sizes = excluded.sizes, is_customizable = excluded.is_customizable, sort_order = excluded.sort_order, updated_at = now();

notify pgrst, 'reload schema';
select count(*) filter (where is_active) as aktif, count(*) filter (where is_active and price > 0) as punya_harga, count(*) filter (where is_active and price = 0) as tanya_harga from public.products;
